class 开饭铃:
    def __init__(self):
        self.听众 = []
    def 订上(self, 猫):
        self.听众.append(猫)
    def 摇铃(self, 菜名):
        for 猫 in self.听众:
            猫.听见了(菜名)

class 猫:
    def __init__(self, 名字):
        self.名字 = 名字
    def 听见了(self, 菜名):
        print(self.名字, "冲向", 菜名)

铃 = 开饭铃()
铃.订上(猫("小橘"))
铃.订上(猫("狸花"))
铃.摇铃("小鱼干")
铃.摇铃("猫粮")
